			},
			want: "400 urn:ietf:params:acme:error:rateLimited: too many registrations for this IP",
		},
		"a conformant problem document is recognised regardless of casing": {
			err: &acmeapi.Error{
				StatusCode:  400,
				ProblemType: "URN:IETF:PARAMS:ACME:ERROR:badCSR",
