// is no existing CertificateRequest resource.
func currentSecretValidForSpec(input Input) (string, string, bool) {
	x509Cert, err := pki.DecodeX509CertificateBytes(input.Secret.Data[corev1.TLSCertKey])
	if err != nil {
		return InvalidCertificate, fmt.Sprintf("Issuing certificate as Secret contains an invalid certificate: %v", err), true
	}
	//nolint: staticcheck // FuzzyX509AltNamesMatchSpec is used here for backwards compatibility
	violations := pki.FuzzyX509AltNamesMatchSpec(x509Cert, input.Certificate.Spec)
	if len(violations) > 0 {
		return SecretMismatch, fmt.Sprintf("Issuing certificate as Existing issued Secret is not up to date for spec: %v", violations), true
	}

	return "", "", false
}

// CurrentCertificateNearingExpiry returns a policy function that can be used to
// check whether an X.509 cert currently issued for a Certificate should be
// renewed.
func CurrentCertificateNearingExpiry(c clock.Clock) Func {
	return func(input Input) (string, string, bool) {
		x509Cert, err := pki.DecodeX509CertificateBytes(input.Secret.Data[corev1.TLSCertKey])
		if err != nil {
			return InvalidCertificate, fmt.Sprintf("Issuing certificate as Secret contains an invalid certificate: %v", err), true
		}

		// Determine if the certificate is nearing expiry solely by looking at
		// the actual cert, if it exists. We assume that at this point we have
		// called policy functions that check that input.Secret and
		// input.Secret.Data exists (SecretDoesNotExist and SecretIsMissingData).

		notBefore := metav1.NewTime(x509Cert.NotBefore)
		notAfter := metav1.NewTime(x509Cert.NotAfter)
		crt := input.Certificate

		// If the certificate renewal policy is set to Disabled, do not renew.
		if crt.Spec.Renewal != nil && crt.Spec.Renewal.Policy == cmapi.CertificateRenewalPolicyDisabled {
			return "", "", false
		}

		reason := Renewing

		if input.ARIRenewalInfo != nil &&
			!input.ARIRenewalInfo.SuggestedWindow.Start.IsZero() {
			window := input.ARIRenewalInfo.SuggestedWindow
			// RFC 9773 asks clients to select a uniform random time within the
			// suggested window so the CA can spread renewal load. The readiness
			// controller picks and persists that time in Status.RenewalTime; gate on
			// it when it demonstrably falls inside the current window. If it does
			// not (the window has moved, or the field still holds a renewBefore
			// value), fall back to the window start so the CA's instruction is never
			// deferred past the window itself.
			gateTime := window.Start
			if rt := crt.Status.RenewalTime; rt != nil &&
				rt.Time.After(x509Cert.NotBefore) &&
				!rt.Time.Before(window.Start) &&
				!rt.Time.After(window.End) {
				gateTime = rt.Time
			}
			if c.Now().Before(gateTime) {
				return "", "", false
			}
			// Report the time the gate actually used, which is the window start
			// when Status.RenewalTime is nil or lies outside the window.
			return reason, fmt.Sprintf("Renewing certificate as renewal was scheduled at %s", gateTime), true
		}

		renewalTime, err := pki.RenewalTime(notBefore.Time, notAfter.Time, crt.Spec.RenewBefore, crt.Spec.RenewBeforePercentage, crt.Spec.Renewal)
		var message string
		if err != nil {
			reason = WindowError
			message = err.Error()
		} else {
			// Report the computed renewal time, which is what this check gates
			// on. Status.RenewalTime may be nil or out of date.
			message = fmt.Sprintf("Renewing certificate as renewal was scheduled at %s", renewalTime)
		}

		renewIn := renewalTime.Time.Sub(c.Now())
		if renewIn > 0 {
			// renewal time is in the future, no need to renew
			return "", "", false
		}

		return reason, message, true
	}
}

// CurrentCertificateHasExpired is used exclusively to check if the current
// issued certificate has actually expired rather than just nearing expiry.
func CurrentCertificateHasExpired(c clock.Clock) Func {
	return func(input Input) (string, string, bool) {
		x509Cert, err := pki.DecodeX509CertificateBytes(input.Secret.Data[corev1.TLSCertKey])
		if err != nil {
			return InvalidCertificate, fmt.Sprintf("Issuing certificate as Secret contains an invalid certificate: %v", err), true
		}

		if c.Now().After(x509Cert.NotAfter) {
			return Expired, fmt.Sprintf("Certificate expired on %s", x509Cert.NotAfter.Format(time.RFC1123)), true
		}
		return "", "", false
	}
