576	func (a *Acme) getEABKey(ctx context.Context, ns string, eab cmmeta.SecretKeySelector) ([]byte, error) {
577		sec, err := a.secretsClient.Secrets(ns).Get(ctx, eab.Name, metav1.GetOptions{})
578		// Surface IsNotFound API error to not cause re-sync
579		if apierrors.IsNotFound(err) {
580			return nil, err
581		}
582	
583		if err != nil {
584			return nil, fmt.Errorf(messageTemplateFailedToGetEABKey, err)
585		}
586	
587		encodedKeyData, ok := sec.Data[eab.Key]
588		if !ok {
589			return nil, cmerrors.NewInvalidData("failed to find external account binding key data in Secret %q at index %q", eab.Name, eab.Key)
590		}
591		if len(encodedKeyData) == 0 {
592			return nil, cmerrors.NewInvalidData("external account binding key data in Secret %q at index %q is empty", eab.Name, eab.Key)
593		}
594	
595		// decode the base64 encoded secret key data.
596		// we include this step to make it easier for end-users to encode secret
597		// keys in case the CA provides a key that is not in standard, padded
598		// base64 encoding.
599		keyData := make([]byte, base64.RawURLEncoding.DecodedLen(len(encodedKeyData)))
600		n, err := base64.RawURLEncoding.Decode(keyData, encodedKeyData)
601		if err != nil {
602			return nil, cmerrors.NewInvalidData("failed to decode external account binding key data: %v", err)
603		}
604		if n == 0 {
605			return nil, cmerrors.NewInvalidData("external account binding key data in Secret %q at index %q is empty", eab.Name, eab.Key)
606		}
607	
608		return keyData[:n], nil
609	}
